import { describe, it, expect } from 'vitest';
import {
  isValidSvg,
  optimizeSvg,
  calculateSvgStats,
  DEFAULT_SVG_OPTIONS,
} from './svgOptimizerLogic';

describe('svgOptimizerLogic', () => {
  const sampleRawSvg = `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.1//EN" "http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd">
<!-- Generated by Illustrator -->
<svg xmlns="http://www.w3.org/2000/svg" xmlns:inkscape="http://www.inkscape.org/namespaces/inkscape" viewBox="0 0 100.55555 100.88888">
  <metadata>
    <rdf:RDF>Sample meta</rdf:RDF>
  </metadata>
  <sodipodi:namedview id="base" />
  <g id="layer_1">
    <path d="M 10.12345 20.67891 L 30.99999 40.11111" inkscape:connector-curvature="0" />
  </g>
</svg>`;

  describe('isValidSvg', () => {
    it('recognizes valid SVG strings', () => {
      expect(isValidSvg('<svg viewBox="0 0 10 10"></svg>')).toBe(true);
      expect(isValidSvg('<div>not svg</div>')).toBe(false);
      expect(isValidSvg('')).toBe(false);
    });
  });

  describe('optimizeSvg', () => {
    it('strips XML processing instruction, doctype, and comments', () => {
      const optimized = optimizeSvg(sampleRawSvg, DEFAULT_SVG_OPTIONS);
      expect(optimized).not.toContain('<?xml');
      expect(optimized).not.toContain('<!DOCTYPE');
      expect(optimized).not.toContain('Generated by Illustrator');
    });

    it('strips metadata and editor namespace attributes', () => {
      const optimized = optimizeSvg(sampleRawSvg, DEFAULT_SVG_OPTIONS);
      expect(optimized).not.toContain('<metadata');
      expect(optimized).not.toContain('xmlns:inkscape');
      expect(optimized).not.toContain('sodipodi:namedview');
      expect(optimized).not.toContain('inkscape:connector-curvature');
    });

    it('rounds coordinate precision to specified decimal places', () => {
      const optimized = optimizeSvg(sampleRawSvg, {
        ...DEFAULT_SVG_OPTIONS,
        precision: 2,
      });
      expect(optimized).toContain('10.12 20.68');
      expect(optimized).toContain('0 0 100.56 100.89');
    });

    it('collapses redundant whitespace', () => {
      const optimized = optimizeSvg(sampleRawSvg, DEFAULT_SVG_OPTIONS);
      expect(optimized).not.toContain('\n');
      expect(optimized).toContain('><');
    });
  });

  describe('calculateSvgStats', () => {
    it('computes byte differences and savings percentage', () => {
      const original = sampleRawSvg;
      const optimized = optimizeSvg(original, DEFAULT_SVG_OPTIONS);
      const stats = calculateSvgStats(original, optimized);

      expect(stats.originalBytes).toBeGreaterThan(stats.optimizedBytes);
      expect(stats.savedBytes).toBe(stats.originalBytes - stats.optimizedBytes);
      expect(stats.savingsPercentage).toBeGreaterThan(20);
    });
  });
});
